types.declaration:
export type AgentContext = Omit<Context, 'remote'> & {
    readonly remote: ClientRemote & TypertRemoteScopeApi<'agent'>;
};

export interface AssistantLiveChunkEvent {
    readonly type: 'assistant/live-chunk';
    readonly seq: number;
    readonly time: number;
    readonly data: {
        readonly attemptId: LlmAttemptId;
        readonly turn: number;
        readonly step: number;
        readonly chunk: StreamChunk;
    };
}

export type BakedActions<T, A extends ActionsDecl<T>> = {
    [K in keyof A]: A[K] extends (draft: T, ...params: infer P) => void ? (...params: P) => void : never;
};

export interface BeginSubmissionInput {
    readonly mode: 'queue' | 'steer';
    readonly text: string;
    readonly attachments: readonly PendingSubmissionAttachment[];
    readonly onAccept?: () => void;
    readonly onRetire?: (retirement: PendingSubmissionRetirement) => void;
}

export interface ChainRenderOpts {
    fallback?: ReactNode;
    fallbackOnly?: boolean;
    overlay?: boolean;
}

export type ChildrenDecl = {
    [P in keyof SlotMap & string]?: SlotSpec<SlotMap[P]>;
};

export interface ClientConnectionRpc {
    call(channel: string, endpoint: string, payload: unknown, signal?: AbortSignal): Promise<ConnectionRpcResult<unknown>>;
    readonly open?: (channel: string, endpoint: string, payload: unknown, signal: AbortSignal, uplink?: AsyncIterable<unknown>) => AsyncIterable<unknown>;
}

export interface ClientRemote extends TypertClientRemote {
    $stream<Item>(options: RemoteStreamOptions<Item>): RemoteStream<Item>;
    readonly $host: RemoteHostFacts;
}

export type CommonKeyOf = LocaleNamespaceMap extends {
    common: infer C;
} ? C & string : never;

export interface ConnectionGeneration {
    readonly id: number;
    readonly host: ConnectionHostInfo;
}

export interface ConnectionGenerationState {
    getSnapshot(): ConnectionGeneration | undefined;
    subscribe(listener: () => void): () => void;
}

export interface ConnectionHandle {
    readonly interactions: ConnectionInteractions;
    readonly isLoopback: boolean;
    readonly generation: ConnectionGenerationState;
    readonly state: ConnectionStateSource;
    readonly rpc: ClientConnectionRpc;
    openWebSocket(path: string): ConnectionWebSocket;
    reconnect(): void;
    registerGenerationSource(source: ConnectionGenerationSource): () => void;
    start(sinks: ConnectionSinks, config?: ConnectionRecoveryConfig): ConnectionLoop;
}

export interface ConnectionHostInfo {
    readonly home: string;
}

export interface ConnectionLoop {
    stop(): void;
}

export interface ConnectionRecoveryConfig {
    backoffBaseMs?: number;
    backoffFactor?: number;
    backoffMaxMs?: number;
    generationReadyWarnMs?: number;
    generationReadyTimeoutMs?: number;
}

export interface ConnectionRpcFailure {
    readonly code: string;
    readonly message: string;
    readonly details: object;
}

export type ConnectionRpcResult<T> = {
    readonly ok: true;
    readonly value: T;
} | {
    readonly ok: false;
    readonly error: ConnectionRpcFailure;
};

export interface ConnectionSinks {
    onConnected?: (host: ConnectionHostInfo) => void;
    onStateChange?: (state: ConnectionState) => void;
    onReconnectRequested?: () => void;
}

export interface ConnectionStateSource {
    getSnapshot(): ConnectionState | undefined;
    subscribe(listener: () => void): () => void;
}

export interface ConnectionWebSocket {
    readonly readyState: number;
    send(data: string): void;
    close(code?: number, reason?: string): void;
    addEventListener<Event extends keyof ConnectionWebSocketEventMap>(event: Event, listener: (event: ConnectionWebSocketEventMap[Event]) => void, options?: {
        readonly once?: boolean;
    }): void;
    removeEventListener<Event extends keyof ConnectionWebSocketEventMap>(event: Event, listener: (event: ConnectionWebSocketEventMap[Event]) => void): void;
}

export interface ConnectionWebSocketEventMap {
    readonly open: object;
    readonly error: object;
    readonly close: object;
    readonly message: {
        readonly data: unknown;
    };
}

export interface DraftInitializationOptions {
    readonly prompt?: string;
    readonly clearPreviousDraft?: boolean;
    readonly whenDraftExists?: 'replace' | 'append' | 'keep';
}

export type EntryKeyOf<K extends keyof SlotMap & string> = SlotMap[K] extends {
    kind: 'keyed';
    keyProps: infer P extends object;
} ? keyof P & string : string;

export type FactoryComponentPropsOf<F extends keyof SlotFactoryMap & string> = FactoryInputPropsOf<F> & FactoryRegistrationPropsOf<F> & ScopeStandardProps<FactoryDefOf<F>['scope']> & {
    useFactorySlot: UseFactorySlot<F>;
};

export type FactoryInjectParams<F extends keyof SlotFactoryMap & string> = FactoryDefOf<F>['scope'] extends 'session' ? ([
    FactoryStoreOf<F>
] extends [
    StoreDecl
] ? [
    sessionId: SessionIdOf,
    actions: BoundActions<FactoryStoreOf<F>>
] : [
    sessionId: SessionIdOf
]) : FactoryDefOf<F>['scope'] extends 'session-maybe' ? ([
    FactoryStoreOf<F>
] extends [
    StoreDecl
] ? [
    sessionId: SessionIdOf | undefined,
    actions: BoundActions<FactoryStoreOf<F>> | undefined
] : [
    sessionId: SessionIdOf | undefined
]) : ([
    FactoryStoreOf<F>
] extends [
    StoreDecl
] ? [
    actions: BoundActions<FactoryStoreOf<F>>
] : [
]);

export type HocShare<E extends SlotEntryDef> = E['kind'] extends 'hoc' ? {
    children: ReactNode;
} : object;

export type InjectFace<I extends object> = I extends {
    hooks: infer HS extends HooksSources;
} ? I extends {
    keyedHooks: infer KS extends KeyedHooksSources;
} ? Omit<I, 'hooks' | 'keyedHooks'> & PropsHooks<HS> & PropsKeyedHooks<KS> : Omit<I, 'hooks'> & PropsHooks<HS> : I extends {
    keyedHooks: infer KS extends KeyedHooksSources;
} ? Omit<I, 'keyedHooks'> & PropsKeyedHooks<KS> : I;

export type InjectParams<K extends keyof SlotMap & string, H> = ScopeOf<K> extends 'session' ? ([
    H
] extends [
    StoreDecl
] ? [
    sessionId: SessionIdOf,
    actions: BoundActions<HandleOf<H>>
] : [
    sessionId: SessionIdOf
]) : ScopeOf<K> extends 'session-maybe' ? ([
    H
] extends [
    StoreDecl
] ? [
    sessionId: SessionIdOf | undefined,
    actions: BoundActions<HandleOf<H>> | undefined
] : [
    sessionId: SessionIdOf | undefined
]) : ([
    H
] extends [
    StoreDecl
] ? [
    actions: BoundActions<HandleOf<H>>
] : [
]);

export interface ISession {
    readonly sessionId: SessionId;
    readonly projections: ProjectionsFace;
    beginSubmission(input: BeginSubmissionInput): SubmissionHandle;
    prompt(content: PromptContentPart[], mode: 'queue' | 'steer', signal?: AbortSignal, requestId?: SessionRequestId): Promise<RemoteResult<{
        accepted: true;
    }>>;
    readAttachment(attachment: ImageAttachmentRef): Promise<RemoteResult<{
        attachment: ImageAttachmentRef;
        data: Uint8Array;
    }>>;
    updateQueue(itemId: MessageId, action: QueueAction): Promise<RemoteResult<{
        accepted: true;
    }>>;
    cancel(): Promise<RemoteResult<{
        accepted: true;
    }>>;
    rename(title: string): Promise<RemoteResult<{
        title: string;
        seq: SessionSeq;
    }>>;
    loadOlder(options?: {
        deferConsumption?: boolean;
    }): Promise<void>;
    consumeOlder(): boolean;
    loadThrough(seq: SessionSeq): Promise<void>;
    command(line: string): Promise<RemoteResult<{
        matched: boolean;
    }>>;
}

export interface ISessions {
    readonly list: ObservableSnapshot<SessionListState>;
    retain(target: SessionTarget, options: SessionRetainOptions): SessionReference;
    using<T>(target: SessionTarget, options: SessionRetainOptions, operation: (reference: SessionReference) => T | Promise<T>): Promise<T>;
    retainInfo(id: SessionId): ObservableSnapshot<SessionRetainInfo>;
    readonly searchResultLimit: number;
    create(opts?: {
        workspaceId?: WorkspaceId;
        cwd?: string;
        sessionId?: SessionId;
        agentPreset?: string;
    }): Promise<SessionId>;
    subagentAddress(id: SessionId): SubagentAddress | undefined;
    refreshProjections(sessionId: SessionId): Promise<void>;
    refresh(): Promise<void>;
    search(query: string, signal: AbortSignal): Promise<RemoteResult<{
        items: SessionSearchResultItem[];
        hasMore: boolean;
    }>>;
    fork(opts: {
        sessionId: SessionId;
        atSeq?: number;
        increaseTitle?: boolean;
        onCreated?: (childId: SessionId) => void;
        allowMigration?: boolean;
    }): Promise<SessionId>;
    scope(id: SessionId): AgentContext | undefined;
    scopeOf(ctx: Context): SessionId | undefined;
    sessionOf(ctx: Context): SessionFace | undefined;
    binding(id: SessionId): SessionBinding | undefined;
}

export type KeyedSnapshotSelectorHook<Snapshot> = {
    (key: string): Snapshot | undefined;
    <Selected>(key: string, selector: (value: Snapshot | undefined) => Selected, equal?: (left: Selected, right: Selected) => boolean): Selected;
};

export type KeyPropsOf<K extends keyof SlotMap & string, EntryKey extends EntryKeyOf<K>> = SlotMap[K] extends {
    kind: 'keyed';
    keyProps: infer P extends object;
} ? EntryKey extends keyof P ? P[EntryKey] extends object ? P[EntryKey] : never : never : object;

export interface LanguageRegistration {
    id: LocaleId;
    label: string;
    fallback: LocaleId;
}

export interface LiveFactoryNode {
    type: 'factory';
    name: string;
    scope: SlotScope;
    registrant?: string;
    children: LiveSlotNode[];
}

export interface LiveSlotNode {
    type: 'slot';
    name: string;
    kind: SlotKind;
    scope: SlotScope;
    declaredBy?: string;
    occupants: LiveSlotOccupant[];
    children: LiveSlotNode[];
}

export interface LiveSlotOccupant {
    registrant?: string;
    key?: string;
    id?: string;
    order?: number;
    priority: number;
    active: boolean;
}

export interface LocaleDefinition {
    readonly id: LocaleId;
    readonly label: string;
    readonly fallback?: LocaleId;
}

export interface LocaleSnapshot {
    active: LocaleId;
    locales: readonly LocaleDefinition[];
    revision: number;
}

export type MatchedShare<E extends SlotEntryDef, M> = E['kind'] extends 'chain' ? {
    matched: M;
} : object;

export interface ObservableSnapshot<T> {
    getSnapshot(): T;
    subscribe(fn: () => void): () => void;
}

export type OwnerOf<K extends keyof SlotMap & string> = SlotMap[K] extends {
    owner: infer O extends object;
} ? O : object;

export interface PendingSubmission {
    readonly requestId: SessionRequestId;
    readonly placement: PendingSubmissionPlacement;
    readonly time: number;
    readonly text: string;
    readonly attachments: readonly PendingSubmissionAttachment[];
}

export interface PendingSubmissionFileAttachment {
    readonly type: 'file';
    readonly value: FileAttachmentRef;
}

export interface PendingSubmissionImage {
    readonly previewUrl: string;
    readonly name?: string;
    readonly width?: number;
    readonly height?: number;
}

export interface PendingSubmissionImageAttachment {
    readonly type: 'image';
    readonly value: PendingSubmissionImage;
}

export type PendingSubmissionRetirement = {
    readonly reason: 'observed';
    readonly attachments: readonly (ImageAttachmentRef | FileAttachmentRef)[];
} | {
    readonly reason: 'failed';
};

export interface ProjectionsFace {
    faceOf(key: string): ObservableSnapshot<unknown>;
}

export type PromptContentPart = {
    readonly type: 'text';
    readonly text: string;
} | {
    readonly type: 'image';
    readonly mediaType: ImageMediaType;
    readonly data: string;
    readonly name?: string;
} | {
    readonly type: 'file';
    readonly receiptId: Branded<'file-upload-receipt-id'>;
};

export interface PromptError {
    readonly op: 'send' | 'stop';
    readonly error: RemoteFailure;
}

export type PropsHooks<HS extends HooksSources> = {
    [N in keyof HS & string as `use${Capitalize<N>}`]: SnapshotSelectorHook<HS[N] extends HostObservable<infer T> ? T : never>;
};

export type PropsKeyedHooks<HS extends KeyedHooksSources> = {
    [N in keyof HS & string as `use${Capitalize<N>}`]: KeyedSnapshotSelectorHook<HS[N] extends (key: string) => HostObservable<infer T> | undefined ? T : never>;
};

export type PropsLocale<N> = N extends keyof LocaleNamespaceMap & string ? {
    t: TranslateNS<N>;
} : object;

export interface PropsRenderFactories {
    renderFactorySlot: RenderFactorySlot;
}

export type PropsRenderSlots<S extends keyof SlotMap & string> = {
    renderSlot: RenderSlotFn<Exclude<S, ChainKeysOf<S>>>;
    readonly __renders?: ((key: S) => void) | undefined;
} & ([
    ChainKeysOf<S>
] extends [
    never
] ? object : {
    renderSlotChain: <K extends ChainKeysOf<S>>(key: K, owner: OwnerOf<K>, opts?: ChainRenderOpts) => ReactNode;
}) & ([
    Extract<ScopeOf<S>, 'session' | 'session-maybe'>
] extends [
    never
] ? object : {
    SessionProvider: SessionProviderComponent;
});

export type PropsSlotHooks<HS extends object> = {
    [N in keyof HS & string as `use${Capitalize<N>}`]: BoundHookOf<HS[N]>;
};

export type PropsStore<H> = H extends StoreHandle<infer T, infer A> ? {
    useStore: SnapshotSelectorHook<T>;
    actions: BakedActions<T, A>;
} : object;

export type QueueAction = {
    readonly kind: 'edit';
    readonly content: readonly TextBlock[];
} | {
    readonly kind: 'remove';
} | {
    readonly kind: 'steer';
};

export interface RegisterFactory {
    <F extends keyof SlotFactoryMap & string>(options: RegisterFactoryOptions<F>, component: SlotComponent<FactoryComponentPropsOf<F>>): () => void;
}

export type RegisterFactoryOptions<F extends keyof SlotFactoryMap & string> = {
    name: F;
    scope: FactoryDefOf<F>['scope'];
} & FactoryField<F, 'children', FactoryChildrenOf<F>> & FactoryField<F, 'store', FactoryStoreOf<F> | (() => FactoryStoreOf<F>)> & FactoryField<F, 'inject', (...args: FactoryInjectParams<F>) => FactoryInjectOf<F>> & FactoryField<F, 'locale', FactoryLocaleOf<F>> & FactoryField<F, 'slots', RuntimeFactorySlots<F>> & FactoryCollisionCheck<F> & FactoryChildrenCheck<F>;

export interface RemoteHostFacts {
    readonly home: string | undefined;
    readonly isLoopback: boolean;
}

export class RemoteStream<Item> implements AsyncIterable<RemoteStreamItem<Item>> {
    constructor(private readonly connection: Pick<ConnectionHandle, 'generation'>, private readonly options: RemoteStreamOptions<Item>);
    get signal(): AbortSignal;
    restart(): void;
    dispose(): Promise<void>;
    [Symbol.asyncIterator](): AsyncIterator<RemoteStreamItem<Item>>;
}

export class RemoteStreamCarrierError extends Error {
    constructor(message: string, options?: ErrorOptions);
}

export interface RemoteStreamItem<Item> {
    readonly generation: number;
    readonly value: Item;
    readonly signal: AbortSignal;
    accept(): void;
}

export interface RemoteStreamOptions<Item> {
    readonly name: string;
    readonly open: (signal: AbortSignal) => AsyncIterable<Item>;
    readonly ended: (accepted: boolean) => Error;
    readonly carrierFailed?: (error: RemoteStreamCarrierError) => void;
}

export type RenderFactorySlot = <F extends keyof SlotFactoryMap & string>(name: F, props: FactoryInputPropsOf<F>, options?: {
    slots?: Partial<{
        [N in FactoryLocalNameOf<F>]: FactoryLocalComponent<F, N>;
    }>;
    fallback?: ReactNode;
}) => ReactNode;

export interface SessionAreaProps {
    readonly session?: SlotScopeTargetMap[keyof SlotScopeTargetMap & 'session'] | undefined;
    empty?: (() => ReactNode) | undefined;
    children: ReactNode;
}

export interface SessionAssistantSettlementEntry {
    readonly type: 'event';
